// Aegyptus (DLC03) filters: tile totals and mine slots of the Egypt session (see EgyptGenerator/EgyptMetrics). The session map is
// fixed, so only the map size (which islands use their smaller "_layer01" variant), the fertility setting and the resource slot
// setting change the value ranges; the map template and DLC01 do not matter.
internal enum EgyptFilter{Buildable,Riverbank,MineSlots,HippoRiverbank,PomegranateTiles,FertileGround,LavenderTiles,GrapeTiles,OliveTiles,MineralMines,TinMines,CopperMines,GoldIslands,GoldMines}
// Step: the slider step (tiles, or 1 for mine slots). Icon: GUID of the icon (a fertility or a good), 0 for none.
internal sealed record EgyptFilterDefinition(EgyptFilter Filter,int Step,uint Icon,Func<EgyptMetrics,int> Value);

internal static class EgyptFilters
{
 public const int Count=14;
 // Good Egyptian Dates: a forest production, it grows only on the native fertile ground.
 public const uint DatesIcon=151680;
 // The order matches the EgyptFilter enum, so a definition can be found by its index.
 public static readonly EgyptFilterDefinition[] All=
 [
  new(EgyptFilter.Buildable,1000,0,x=>x.BuildableTiles),
  new(EgyptFilter.Riverbank,500,0,x=>x.RiverbankTiles),
  new(EgyptFilter.MineSlots,1,0,x=>x.MineSlots),
  new(EgyptFilter.HippoRiverbank,500,EgyptGenerator.Hippos,x=>x.HippoRiverbankTiles),
  new(EgyptFilter.PomegranateTiles,1000,EgyptGenerator.Pomegranates,x=>x.PomegranateTiles),
  new(EgyptFilter.FertileGround,500,DatesIcon,x=>x.FertileGround),
  new(EgyptFilter.LavenderTiles,1000,EgyptGenerator.Lavender,x=>x.LavenderTiles),
  new(EgyptFilter.GrapeTiles,1000,EgyptGenerator.Grapes,x=>x.GrapeTiles),
  new(EgyptFilter.OliveTiles,1000,EgyptGenerator.Olives,x=>x.OliveTiles),
  new(EgyptFilter.MineralMines,1,EgyptGenerator.Minerals,x=>x.MineralMines),
  new(EgyptFilter.TinMines,1,EgyptGenerator.Tin,x=>x.TinMines),
  new(EgyptFilter.CopperMines,1,EgyptGenerator.Copper,x=>x.CopperMines),
  new(EgyptFilter.GoldIslands,1,EgyptGenerator.Gold,x=>x.GoldIslands),
  new(EgyptFilter.GoldMines,1,EgyptGenerator.Gold,x=>x.GoldMines),
 ];
 public static EgyptFilterDefinition Get(EgyptFilter filter)=>All[(int)filter];
 public static int[] Values(EgyptMetrics metrics)=>[..All.Select(definition=>definition.Value(metrics))];
}

